3	module cmp_32(  input [31:0] a,
4	                input [31:0] b,
5	                input [2:0] ctrl,
6	                output c
7	    );
8	    localparam cmp_EQ  = 3'b001;
9	    localparam cmp_NE  = 3'b010;
10	    localparam cmp_LT  = 3'b011;
11	    localparam cmp_LTU = 3'b100;
12	    localparam cmp_GE  = 3'b101;
13	    localparam cmp_GEU = 3'b110;
14	
15	    wire res_EQ  = a == b;
16	    wire res_NE  = ~res_EQ;
17	    wire res_LT  = (a[31] & ~b[31]) || (~(a[31] ^ b[31]) && a < b);
18	    wire res_LTU = a < b;
19	    wire res_GE  = ~res_LT;
20	    wire res_GEU = ~res_LTU;
21	
22	    wire EQ  = ctrl == cmp_EQ ; 
23	    wire NE  = ctrl == cmp_NE ; 
24	    wire LT  = ctrl == cmp_LT ; 
25	    wire LTU = ctrl == cmp_LTU;
26	    wire GE  = ctrl == cmp_GE ; 
27	    wire GEU = ctrl == cmp_GEU;
28	
29	    assign c = EQ  & res_EQ  |
30	               NE  & res_NE  |
31	               LT  & res_LT  |
32	               LTU & res_LTU |
33	               GE  & res_GE  |
34	               GEU & res_GEU ;
35	    
36	
37	endmodule

