24	    wire[31:0] res_SUB  = A - B;
25	    wire[31:0] res_AND  = A & B;
26	    wire[31:0] res_OR   = A | B;
27	    wire[31:0] res_XOR  = A ^ B;
28	    wire[31:0] res_SLL  = A << B[4:0];
29	    wire[31:0] res_SRL  = A >> B[4:0];
30	    wire[31:0] res_SLT  = ($signed(A) < $signed(B)) ? 32'd1 : 32'd0;
31	    wire[31:0] res_SLTU = (A < B) ? 32'd1 : 32'd0;
32	    wire[31:0] res_SRA  = $signed(A) >>> B[4:0];
33	    wire[31:0] res_Ap4  = A + 32'd4;
34	    wire[31:0] res_Bout = B;
35	
36	    assign res = {32{Control == ALU_ADD}}  & res_ADD  |
37	                 {32{Control == ALU_SUB}}  & res_SUB  |
38	                 {32{Control == ALU_AND}}  & res_AND  |
39	                 {32{Control == ALU_OR}}   & res_OR   |
40	                 {32{Control == ALU_XOR}}  & res_XOR  |
41	                 {32{Control == ALU_SLL}}  & res_SLL  |
