3	module RAM_B(
4	    input [31:0] addra,
5	    input clka,      // normal clock
6	    input[31:0] dina,
7	    input wea, 
8	    output[31:0] douta,
9	    output [7:0] sim_uart_char_out,
10	    output sim_uart_char_valid,
11	    input[2:0] mem_u_b_h_w
12	);
13	    localparam SIZE = 256;
14	    localparam ADDR_LINE = $clog2(SIZE);
15	    localparam SIM_UART_ADDR = 32'h10000000;
16	
17	    reg[7:0] data[0:SIZE-1];
18	
19	    initial	begin
20	        $readmemh("ram.mem", data);
21	    end
22	
23	    wire uart_sel = addra == SIM_UART_ADDR;
24	    wire[ADDR_LINE-1:0] addr = addra[ADDR_LINE-1:0];
25	
26	    // mem_u_b_h_w[1]=1 -> word, mem_u_b_h_w[0]=1 -> halfword, otherwise byte
27	    wire wr_word = mem_u_b_h_w[1];
28	    wire wr_half = mem_u_b_h_w[0];
29	
30	    // byte-addressable write logic (writes to the simulated UART are excluded;
31	    // the RAM is aliased over the whole address space via the low address bits)
32	    always @(posedge clka) begin
33	        if (wea && !uart_sel) begin
34	            if (wr_word) begin
35	                data[addr]     <= dina[7:0];
36	                data[addr + 1] <= dina[15:8];
37	                data[addr + 2] <= dina[23:16];
38	                data[addr + 3] <= dina[31:24];
39	            end
40	            else if (wr_half) begin
41	                data[addr]     <= dina[7:0];
42	                data[addr + 1] <= dina[15:8];
43	            end
44	            else begin
45	                data[addr]     <= dina[7:0];
46	            end
47	        end
48	    end
49	
50	    // combinational read; mem_u_b_h_w[2]=1 -> unsigned (zero-extend)
51	    wire[31:0] rd_word = {data[addr + 3], data[addr + 2], data[addr + 1], data[addr]};
52	    wire[31:0] rd_half = mem_u_b_h_w[2] ? {16'b0, data[addr + 1], data[addr]} :
53	                         {{16{data[addr + 1][7]}}, data[addr + 1], data[addr]};
54	    wire[31:0] rd_byte = mem_u_b_h_w[2] ? {24'b0, data[addr]} :
55	                         {{24{data[addr][7]}}, data[addr]};
56	
57	    assign douta = uart_sel ? 32'b0 :
58	                   wr_word  ? rd_word :
59	                   wr_half  ? rd_half :
60	                              rd_byte;
61	
62	    // simulated UART output: latch the character of a store to SIM_UART_ADDR
63	    reg[7:0] uart_char;
64	    reg uart_valid;
65	    always @(posedge clka) begin
66	        if (wea && uart_sel) begin
67	            uart_char  <= dina[7:0];
68	            uart_valid <= 1'b1;
69	        end
70	        else begin
71	            uart_valid <= 1'b0;
72	        end
73	    end
74	    assign sim_uart_char_out = uart_char;
75	    assign sim_uart_char_valid = uart_valid;
76	
77	endmodule

