module FU_div(
    input clk, EN,
    input[31:0] A, B,
    output[31:0] res,
    output finish
);

    wire res_valid;
    wire[63:0] divres;

    reg state;
    assign finish = res_valid & state;
    initial begin
        state = 0;
    end

    // division functional unit: AXI-style handshake with the divider IP
    reg A_valid, B_valid;
    reg[31:0] A_reg, B_reg;

    initial begin
        A_valid = 0;
        B_valid = 0;
    end

    always @(posedge clk) begin
        if (EN & ~state) begin
            A_reg <= A;
            B_reg <= B;
            A_valid <= 1'b1;
            B_valid <= 1'b1;
            state <= 1'b1;
        end
        else if (res_valid) begin
            A_valid <= 1'b0;
            B_valid <= 1'b0;
            state <= 1'b0;
        end
        else begin
            A_valid <= 1'b0;
            B_valid <= 1'b0;
        end
    end

    divider div(
        .aclk(clk),
        .s_axis_dividend_tvalid(A_valid),
        .s_axis_dividend_tdata(A_reg),
        .s_axis_divisor_tvalid(B_valid),
        .s_axis_divisor_tdata(B_reg),
        .m_axis_dout_tvalid(res_valid),
        .m_axis_dout_tdata(divres)
    );

    // quotient is the upper 32 bits of the divider result
    assign res = divres[63:32];

endmodule

