// Behavioral simulation model of the multiplier IP core.
// Signed 32x32 -> 64 multiplication; the low 32 bits are identical
// for signed and unsigned operands, so MUL works either way.
module multiplier(
    input CLK,
    input[31:0] A,
    input[31:0] B,
    output[63:0] P
);

    wire signed[63:0] A_ext = {{32{A[31]}}, A};
    wire signed[63:0] B_ext = {{32{B[31]}}, B};

    assign P = A_ext * B_ext;

endmodule

