// Behavioral simulation model of the divider IP core.
// AXI-stream style handshake: when both operand valids are seen while
// idle, the operands are latched and the result is produced after a
// fixed latency. m_axis_dout_tdata = {quotient, remainder} (signed,
// truncated toward zero, following the RISC-V DIV/REM specification).
module divider(
    input aclk,
    input s_axis_dividend_tvalid,
    input[31:0] s_axis_dividend_tdata,
    input s_axis_divisor_tvalid,
    input[31:0] s_axis_divisor_tdata,
    output reg m_axis_dout_tvalid,
    output reg[63:0] m_axis_dout_tdata
);

    localparam LATENCY = 32;

    reg[5:0] count;
    reg[31:0] dividend, divisor;

    reg[31:0] quot, rem;

    initial begin
        m_axis_dout_tvalid = 0;
        m_axis_dout_tdata = 0;
        count = 0;
    end

    always @(posedge aclk) begin
        if (s_axis_dividend_tvalid & s_axis_divisor_tvalid & (count == 0)) begin
            dividend <= s_axis_dividend_tdata;
            divisor <= s_axis_divisor_tdata;
            count <= LATENCY;
            m_axis_dout_tvalid <= 1'b0;
        end
        else if (count != 0) begin
            count <= count - 1;
            if (count == 1) begin
                if (divisor == 32'b0) begin
                    // division by zero: quotient = -1, remainder = dividend
                    quot = 32'hFFFF_FFFF;
                    rem = dividend;
                end
                else if (dividend == 32'h8000_0000 && divisor == 32'hFFFF_FFFF) begin
                    // signed overflow: quotient = dividend, remainder = 0
                    quot = 32'h8000_0000;
                    rem = 32'b0;
                end
                else begin
                    quot = $signed(dividend) / $signed(divisor);
                    rem = $signed(dividend) % $signed(divisor);
                end
                m_axis_dout_tdata <= {quot, rem};
                m_axis_dout_tvalid <= 1'b1;
            end
        end
    end

endmodule

