module FU_mem(
    input clk, EN, mem_w,
    input[2:0] bhw,
    input[31:0] rs1_data, rs2_data, imm,
    output[31:0] mem_data,
    output finish
);

    reg[1:0] state;
    assign finish = state[0] == 1'b1;
    initial begin
        state = 0;
    end

    // memory functional unit: 2-cycle latency modeled by a shifting
    // state register (2'b10 -> 2'b01 -> 2'b00)
    reg mem_w_reg;
    reg[2:0] bhw_reg;
    reg[31:0] rs1_data_reg, rs2_data_reg, imm_reg;

    wire[31:0] addr;

    always @(posedge clk) begin
        if (EN & ~|state) begin
            state <= 2'b10;
            mem_w_reg <= mem_w;
            bhw_reg <= bhw;
            rs1_data_reg <= rs1_data;
            rs2_data_reg <= rs2_data;
            imm_reg <= imm;
        end
        else begin
            state <= {1'b0, state[1]};
        end
    end

    add_32 add_addr(.a(rs1_data_reg), .b(imm_reg), .c(addr));

    RAM_B ram(
        .addra(addr),
        .clka(clk),
        .dina(rs2_data_reg),
        .wea(mem_w_reg & state[1]),
        .douta(mem_data),
        .mem_u_b_h_w(bhw_reg),
        .finish(finish)
    );

endmodule

