    // the tag of the reservation station entry producing the value
    assign rs_num_A = rat[R_addr_A];
    assign rs_num_B = rat[R_addr_B];


    // CDB broadcast writeback: when the broadcast tag matches the RAT
    // entry of a register, that register receives the value. Done on the
    // negedge so that values are settled before the next issue posedge.
    always @(negedge clk or posedge rst)
      begin
		if (rst) 	 begin 			// reset
		    for (i=1; i<32; i=i+1) begin
		      register[i] <= 0;
		    end
		end
		else begin
		    if (|cdb_rs_num) begin
		        for (j=1; j<32; j=j+1) begin
		            if (rat[j] == cdb_rs_num)
		                register[j] <= cdb_data;
		        end
		    end
		end
	end

    // RAT maintenance on the posedge: clear the alias of a register whose
    // producer just broadcast, and record the alias of a newly issued
    // instruction. Updating on the posedge (after issue sampling) keeps an
    // issuing instruction from seeing its own tag in rs_num_A/rs_num_B.
    always @(posedge clk or posedge rst)
      begin
        if (rst) begin
            for (i=0; i<32; i=i+1) begin
                rat[i] <= 8'b0;
            end
        end
        else begin
            // CDB broadcast clears the matching alias
            if (|cdb_rs_num) begin
                for (j=0; j<32; j=j+1) begin
                    if (rat[j] == cdb_rs_num)
                        rat[j] <= 8'b0;
                end
            end
            // issue of a register-writing instruction records the new alias
            if (rs_rd_w_en)
                rat[R_addr_rd] <= rs_num_rd;
        end
    end

    assign Debug_regs = (Debug_addr == 0) ? 0 : register[Debug_addr];               //TEST

endmodule

