`timescale 1ns / 1ps
`include "CtrlDefine.vh"

// Reservation station for one functional unit (Tomasulo).
// Each entry: busy, op, Qj/Qk (producer tags, 0 = value ready),
// Vj/Vk (operand values), A (immediate/address field), PC (debug/jump).
// Tag encoding: {FU type [7:5], entry index [4:0]}.
module RS #(
    parameter FU  = `FU_ALU,   // FU type, forms the upper 3 bits of the tag
    parameter num = 3          // number of entries
)(
    input clk,
    input rst,

    // issue (entry allocation)
    input selected,            // allocate a new entry this cycle
    output [7:0] free_rs,      // tag of a free entry, 0 if none available
    input [4:0] op,
    input [7:0] Qj,
    input [7:0] Qk,
    input [31:0] Vj,
    input [31:0] Vk,
    input [31:0] A,
    input [31:0] pc_IS,

    // dispatch to the functional unit
    output en_FU,              // one-cycle pulse: an entry is dispatched
    output [31:0] vj,
    output [31:0] vk,
    output [4:0] op_out,
    output [31:0] A_o,
    output [31:0] pc_FU,

    // tag of the entry currently inside the FU; its result is expected
    // on the CDB, which also frees the entry
    output [7:0] cdb_rs_rd,

    // CDB snoop
    input [7:0] cdb_rs_num,
    input [31:0] cdb_data,

    output [31:0] pc_debug
);

    reg          busy_r [0:num-1];
    reg [4:0]    op_r   [0:num-1];
    reg [7:0]    Q1_r   [0:num-1];
    reg [7:0]    Q2_r   [0:num-1];
    reg [31:0]   V1_r   [0:num-1];
    reg [31:0]   V2_r   [0:num-1];
    reg [31:0]   A_r    [0:num-1];
    reg [31:0]   PC_r   [0:num-1];

    // entry currently executing in the FU (dispatched, awaiting CDB)
    reg [4:0] in_flight;
    reg       in_flight_valid;

    integer i;

    // lowest-indexed free entry
    reg [4:0] free_idx;
    reg       free_found;
    always @(*) begin
        free_idx = 5'b0;
        free_found = 1'b0;
        for (i = num-1; i >= 0; i = i - 1) begin
            if (!busy_r[i]) begin
                free_idx = i[4:0];
                free_found = 1'b1;
            end
        end
    end
    assign free_rs = free_found ? {FU[2:0], free_idx} : 8'b0;

    // lowest-indexed ready entry (operands available, not yet dispatched)
    reg [4:0] ready_idx;
    reg       ready_found;
    always @(*) begin
        ready_idx = 5'b0;
        ready_found = 1'b0;
        for (i = num-1; i >= 0; i = i - 1) begin
            if (busy_r[i] && (Q1_r[i] == 8'b0) && (Q2_r[i] == 8'b0) &&
                !(in_flight_valid && in_flight == i[4:0])) begin
                ready_idx = i[4:0];
                ready_found = 1'b1;
            end
        end
    end

    // dispatch only when the FU is empty (one instruction at a time)
    assign en_FU  = ready_found & ~in_flight_valid;
    assign vj     = V1_r[ready_idx];
    assign vk     = V2_r[ready_idx];
    assign op_out = op_r[ready_idx];
    assign A_o    = A_r[ready_idx];
    assign pc_FU  = PC_r[ready_idx];

    assign cdb_rs_rd = in_flight_valid ? {FU[2:0], in_flight} : 8'b0;
    assign pc_debug  = in_flight_valid ? PC_r[in_flight] : 32'b0;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            for (i = 0; i < num; i = i + 1) begin
                busy_r[i] <= 1'b0;
                Q1_r[i]   <= 8'b0;
                Q2_r[i]   <= 8'b0;
            end
            in_flight       <= 5'b0;
            in_flight_valid <= 1'b0;
        end
        else begin
            // CDB snoop: wake up waiting operands
            if (|cdb_rs_num) begin
                for (i = 0; i < num; i = i + 1) begin
                    if (busy_r[i] && Q1_r[i] == cdb_rs_num) begin
                        Q1_r[i] <= 8'b0;
                        V1_r[i] <= cdb_data;
                    end
                    if (busy_r[i] && Q2_r[i] == cdb_rs_num) begin
                        Q2_r[i] <= 8'b0;
                        V2_r[i] <= cdb_data;
                    end
                end
            end

            // the CDB broadcast of the in-flight entry frees it
            if (in_flight_valid && cdb_rs_num == {FU[2:0], in_flight}) begin
                busy_r[in_flight] <= 1'b0;
                in_flight_valid   <= 1'b0;
            end

            // dispatch a ready entry to the FU
            if (en_FU) begin
                in_flight       <= ready_idx;
                in_flight_valid <= 1'b1;
            end

            // allocate a new entry (free_idx is valid: issue stalls otherwise)
            if (selected) begin
                busy_r[free_idx] <= 1'b1;
                op_r[free_idx]   <= op;
                Q1_r[free_idx]   <= Qj;
                Q2_r[free_idx]   <= Qk;
                V1_r[free_idx]   <= Vj;
                V2_r[free_idx]   <= Vk;
                A_r[free_idx]    <= A;
                PC_r[free_idx]   <= pc_IS;
            end
        end
    end

endmodule

